import{_ as e,c as a,o as i,a2 as s}from"./chunks/framework.DgH2I27U.js";const g=JSON.parse('{"title":"Git Revert","description":"","frontmatter":{},"headers":[],"relativePath":"fr/undo/revert.md","filePath":"fr/undo/revert.md"}'),t={name:"fr/undo/revert.md"},n=s(`<h1 id="git-revert" tabindex="-1">Git Revert <a class="header-anchor" href="#git-revert" aria-label="Permalink to &quot;Git Revert&quot;">​</a></h1><p>La commande <code>git revert</code> est utilisée lorsque vous souhaitez revenir à un commit précédent en l&#39;ajoutant comme un nouveau commit, tout en préservant l&#39;historique du journal des commits.</p><h2 id="etape-1-trouver-le-commit-precedent" tabindex="-1">Étape 1 : Trouver le commit précédent <a class="header-anchor" href="#etape-1-trouver-le-commit-precedent" aria-label="Permalink to &quot;Étape 1 : Trouver le commit précédent&quot;">​</a></h2><p><img src="https://www.w3schools.com/git/img_revert_part1.gif" alt="Trouver le commit précédent"></p><p>Avant d&#39;effectuer un revert, nous devons identifier le commit auquel nous voulons revenir.</p><h2 id="etape-2-creer-un-nouveau-commit" tabindex="-1">Étape 2 : Créer un nouveau commit <a class="header-anchor" href="#etape-2-creer-un-nouveau-commit" aria-label="Permalink to &quot;Étape 2 : Créer un nouveau commit&quot;">​</a></h2><p><img src="https://www.w3schools.com/git/img_revert_part2.gif" alt="Créer un nouveau commit"></p><p>Une fois le commit trouvé, nous l&#39;utilisons pour effectuer un revert et créer un nouveau commit.</p><h3 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><p>Imaginons que nous ayons effectué un commit où nous avons &quot;accidentellement&quot; supprimé un fichier. Voici l&#39;exemple de commit effectué :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Juste une mise à jour régulière, aucun accident ici...&quot;</span></span></code></pre></div><p>Cela produit le résultat suivant :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[master 16a6f19] Juste une mise à jour régulière, aucun accident ici...</span></span>
<span class="line"><span>1 fichier modifié, 0 insertions(+), 0 suppressions(-)</span></span>
<span class="line"><span>mode de suppression 100644 img_hello_git.jpg</span></span></code></pre></div><p>Nous avons maintenant un commit dans l&#39;historique que nous souhaitons annuler. Utilisons <code>git revert</code> pour revenir à ce commit.</p><h2 id="trouver-le-commit-dans-le-journal" tabindex="-1">Trouver le commit dans le journal <a class="header-anchor" href="#trouver-le-commit-dans-le-journal" aria-label="Permalink to &quot;Trouver le commit dans le journal&quot;">​</a></h2><p>La première étape consiste à trouver le commit auquel nous voulons revenir. Pour cela, nous devons examiner l&#39;historique des commits en utilisant la commande <code>git log</code>.</p><p>Pour éviter un affichage trop long du journal, nous pouvons utiliser l&#39;option <code>--oneline</code>, qui affiche chaque commit sur une seule ligne, avec :</p><ul><li>Les sept premiers caractères du hash du commit</li><li>Le message du commit</li></ul><p>Exemple :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span></code></pre></div><p>Cela renvoie un résultat similaire à ceci :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>52418f7 (HEAD -&gt; master) Juste une mise à jour régulière, aucun accident ici...</span></span>
<span class="line"><span>9a9add8 (origin/master) Ajout du fichier .gitignore</span></span>
<span class="line"><span>81912ba Correction d&#39;une faute de frappe</span></span>
<span class="line"><span>3fdaa5b Fusionner la demande de tirage #1 depuis w3schools-test/update-readme</span></span>
<span class="line"><span>836e5bf (origin/update-readme, update-readme) Mise à jour du README pour GitHub Branches</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Nous voulons revenir au commit <code>52418f7</code>, le dernier commit dans cet exemple.</p><h2 id="utiliser-git-revert-pour-annuler-le-dernier-commit" tabindex="-1">Utiliser <code>git revert</code> pour annuler le dernier commit <a class="header-anchor" href="#utiliser-git-revert-pour-annuler-le-dernier-commit" aria-label="Permalink to &quot;Utiliser \`git revert\` pour annuler le dernier commit&quot;">​</a></h2><p>Pour annuler le dernier commit, nous utilisons la commande suivante :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-edit</span></span></code></pre></div><p>Cela effectuera un revert du dernier commit et l&#39;ajoutera en tant que nouveau commit sans modifier le message du commit, en utilisant le message par défaut de <code>revert</code>.</p><h3 id="exemple-de-sortie" tabindex="-1">Exemple de sortie : <a class="header-anchor" href="#exemple-de-sortie" aria-label="Permalink to &quot;Exemple de sortie :&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[master e56ba1f] Revert &quot;Juste une mise à jour régulière, aucun accident ici...&quot;</span></span>
<span class="line"><span>Date : Thu Apr 22 10:50:13 2021 +0200</span></span>
<span class="line"><span>1 fichier modifié, 0 insertions(+), 0 suppressions(-)</span></span>
<span class="line"><span>mode de création 100644 img_hello_git.jpg</span></span></code></pre></div><h3 id="verification-du-journal-des-commits" tabindex="-1">Vérification du journal des commits <a class="header-anchor" href="#verification-du-journal-des-commits" aria-label="Permalink to &quot;Vérification du journal des commits&quot;">​</a></h3><p>Si nous vérifions à nouveau l&#39;historique des commits avec <code>git log --oneline</code>, nous voyons maintenant que le revert a bien été effectué :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span></code></pre></div><p>Sortie :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e56ba1f (HEAD -&gt; master) Revert &quot;Juste une mise à jour régulière, aucun accident ici...&quot;</span></span>
<span class="line"><span>52418f7 Juste une mise à jour régulière, aucun accident ici...</span></span>
<span class="line"><span>9a9add8 (origin/master) Ajout du fichier .gitignore</span></span>
<span class="line"><span>...</span></span></code></pre></div><h2 id="revenir-a-un-commit-anterieur" tabindex="-1">Revenir à un commit antérieur <a class="header-anchor" href="#revenir-a-un-commit-anterieur" aria-label="Permalink to &quot;Revenir à un commit antérieur&quot;">​</a></h2><p>Pour revenir à un commit plus ancien, utilisez la commande suivante :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD~x</span></span></code></pre></div><p>Où <code>x</code> est le nombre de commits à remonter dans l&#39;historique. Par exemple, <code>HEAD~1</code> revient au commit précédent, <code>HEAD~2</code> revient à deux commits avant, etc.</p><hr><p>Dans la page suivante, nous aborderons la commande <code>git reset</code>, qui permet de ramener le dépôt à un état antérieur sans créer un nouveau commit.</p>`,40),o=[n];function r(l,p,u,c,d,m){return i(),a("div",null,o)}const v=e(t,[["render",r]]);export{g as __pageData,v as default};
